std::vector<WebRecord> WebLearningEngine::crawl(const std::string& start,int maxPages,int maxDepth){std::vector<WebRecord>o;std::wstring u(start.begin(),start.end());URL_COMPONENTSW c{};wchar_t host[256]{},path[2048]{};c.dwStructSize=sizeof(c);c.lpszHostName=host;c.dwHostNameLength=256;c.lpszUrlPath=path;c.dwUrlPathLength=2048;if(!WinHttpCrackUrl(u.c_str(),0,0,&c))return o;HINTERNET s=WinHttpOpen(L"ISO-Tool-Crawler/1.0",WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,nullptr,nullptr,0);if(!s)return o;HINTERNET h=WinHttpConnect(s,host,c.nPort,0);if(!h){WinHttpCloseHandle(s);return o;}HINTERNET r=WinHttpOpenRequest(h,L"GET",path,nullptr,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,c.nScheme==INTERNET_SCHEME_HTTPS?WINHTTP_FLAG_SECURE:0);if(r&&WinHttpSendRequest(r,nullptr,0,nullptr,0,0,0)&&WinHttpReceiveResponse(r,nullptr)){DWORD n=0;std::string body;while(WinHttpQueryDataAvailable(r,&n)&&n){std::string b(n,'\0');DWORD g=0;WinHttpReadData(r,b.data(),n,&g);body.append(b,0,g);}o.push_back({start,body,200});}if(r)WinHttpCloseHandle(r);WinHttpCloseHandle(h);WinHttpCloseHandle(s);return o;}
